  const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
  let ptr = 0;
  const N = Number(data[ptr++]);
  const X1 = BigInt(data[ptr++]);
  const X2 = BigInt(data[ptr++]);

  const lines = new Array(N);
  const y2s = new Array(N);

  for (let i = 0; i < N; i++) {
    const a = BigInt(data[ptr++]);
    const b = BigInt(data[ptr++]);
    const y1 = a * X1 + b;
    const y2 = a * X2 + b;
    lines[i] = { y1, y2, idx: 0 };
    y2s[i] = y2;
  }

