    lines.sort((p, q) => p.y1 < q.y1 ? -1 : p.y1 > q.y1 ? 1 : 0);
    let ans = 0;
    let i = 0;
    while (i < N) {
      let j = i + 1;
      while (j < N && lines[j].y1 === lines[i].y1) j++;
      const k = j - i;
      ans += k * (k - 1) / 2;
      i = j;
    }
    console.log(ans);
    return;
  }

  const sortedY2 = y2s.slice().sort((a, b) => a < b ? -1 : a > b ? 1 : 0);
  const uniqueY2 = [];
  let equalY2Pairs = 0;

  for (let i = 0; i < N; ) {
    let j = i + 1;
    while (j < N && sortedY2[j] === sortedY2[i]) j++;
    const c = j - i;
    equalY2Pairs += c * (c - 1) / 2;
    uniqueY2.push(sortedY2[i]);
    i = j;
  }

  const y2Index = new Map();
  for (let i = 0; i < uniqueY2.length; i++) {
    y2Index.set(uniqueY2[i], i + 1);
  }

  for (let i = 0; i < N; i++) {
    lines[i].idx = y2Index.get(lines[i].y2);
  }

  lines.sort((p, q) => p.y1 < q.y1 ? -1 : p.y1 > q.y1 ? 1 : 0);

  const M = uniqueY2.length;
  const bit = new Array(M + 1).fill(0);

  function add(idx, val) {
    for (; idx <= M; idx += idx & -idx) {
      bit[idx] += val;
    }
  }

  function sum(idx) {
    let s = 0;
    for (; idx > 0; idx -= idx & -idx) {
      s += bit[idx];
    }
    return s;
  }

  let ans = equalY2Pairs;
  let totalPrev = 0;
  let i = 0;

  while (i < N) {
    let j = i + 1;
    while (j < N && lines[j].y1 === lines[i].y1) j++;

    for (let k = i; k < j; k++) {
      const idx = lines[k].idx;
      ans += totalPrev - sum(idx);
    }

    for (let k = i; k < j; k++) {
      add(lines[k].idx, 1);
    }

    const size = j - i;
    ans += size * (size - 1) / 2;
    totalPrev += size;
    i = j;
  }

  console.log(ans);
}

main();
